import Foundation
import Observation

/// Lesson content bundled with the app (generated by backend/tools/build_content.py).
@Observable
final class ContentStore {
    let phonemes: [Phoneme]
    let units: [CourseUnit]
    let minimalPairs: [MinimalPair]
    let readingWords: [WordEntry]
    let sentences: [PracticeSentence]
    let topics: [Topic]
    private let byID: [String: Phoneme]

    init(bundle: Bundle = .main) {
        phonemes = Self.load("phonemes", bundle: bundle)
        units = Self.load("units", bundle: bundle)
        minimalPairs = Self.load("minimal_pairs", bundle: bundle)
        readingWords = Self.load("reading_words", bundle: bundle)
        sentences = Self.load("sentences", bundle: bundle)
        topics = Self.load("topics", bundle: bundle)
        byID = Dictionary(uniqueKeysWithValues: phonemes.map { ($0.id, $0) })
    }

    func phoneme(_ id: String?) -> Phoneme? {
        id.flatMap { byID[$0] }
    }

    func phonemes(in category: Phoneme.Category) -> [Phoneme] {
        phonemes.filter { $0.category == category }
    }

    func phonemes(of unit: CourseUnit) -> [Phoneme] {
        unit.sounds.compactMap { byID[$0] }
    }

    /// Example words from the whole course that contain (or lack) a sound.
    func words(containing id: String) -> [WordEntry] {
        allWords.filter { $0.phones.contains(id) }
    }

    func words(without id: String) -> [WordEntry] {
        allWords.filter { !$0.phones.contains(id) }
    }

    private var allWords: [WordEntry] {
        var seen = Set<String>()
        return (phonemes.flatMap(\.examples) + readingWords).filter { seen.insert($0.word).inserted }
    }

    private static func load<T: Decodable>(_ name: String, bundle: Bundle) -> [T] {
        guard let url = bundle.url(forResource: name, withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let items = try? JSONDecoder().decode([T].self, from: data)
        else {
            assertionFailure("Missing or invalid bundled content \(name).json")
            return []
        }
        return items
    }
}
